return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-02-26 10:57+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Nenda kwenye Utafutaji wa programu-jalizi','Activate %s' => 'Washa %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> inahitaji <strong>%2$s</strong> kusakinishwa na kuamishwa. <a href="%4$s">%3$s</a>','Enter your code here' => 'Weka nambari yako hapa','Add %s' => 'Ongeza %s','Remove' => 'Ondoa','Order number and receipt will be sent to this email address.' => 'Nambari ya agizo na risiti zitatumwa kwa anwani hii ya barua pepe.','Apartment, unit, building, floor, etc.' => 'Ghorofa, kitengo, jengo, sakafu, nk.','Shipping phone' => 'Simu ya kusafirisha','Only used for shipping-related questions.' => 'Inatumika kwa maswali yanayohusiana na usafirishaji pekee.','Single step' => 'Hatua moja','Click to go to the order summary' => 'Bofya ili kwenda kwa muhtasari wa agizo','Cart total:' => 'Jumla ya rukwama:','Proceed to %s' => 'Nenda kwa %s','Proceed to contact' => 'Endelea kuwasiliana','Proceed to shipping' => 'Endelea na usafirishaji','Proceed to billing' => 'Endelea kwenye malipo','Proceed to payment' => 'Endelea hadi malipo','Shipping method' => 'Mbinu ya usafirishaji','Additional notes' => 'Vidokezo vya ziada','Payment method' => 'Njia ya malipo','Step %1$s of %2$s' => 'Hatua ya %1$s ya %2$s','Change: %s' => 'Badilisha: %s','Not selected yet.' => 'Bado haijachaguliwa.','Same as shipping address' => 'Sawa na anwani ya usafirishaji','Same as billing address' => 'Sawa na anwani ya kutuma bili','Order summary' => 'Muhtasari wa agizo','Edit cart' => 'Badilisha rukwama','Did you mean %s?' => 'Je, ulimaanisha %s?','Change email address to: {suggestion-value}' => 'Badilisha anwani ya barua pepe iwe: {suggestion-value}','This is a required field.' => 'Hii ni sehemu inayohitajika.','This is not a valid email address.' => 'Hii si barua pepe halali.','This field does not match the related field value.' => 'Sehemu hii hailingani na thamani ya sehemu husika.','The CPF number "{cpf_number}" is invalid.' => 'Nambari ya CPF &quot;{cpf_number}&quot; si sahihi.','The CNPJ number "{cnpj_number}" is invalid.' => 'Nambari ya CNPJ &quot;{cnpj_number}&quot; si sahihi.','(Required)' => '(Inahitajika)','Checkout Header - Desktop' => 'Kichwa cha Malipo - Eneo-kazi','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Onyesha wijeti kwenye kichwa cha malipo kwa skrini kubwa. Inaonyeshwa tu ikiwa unatumia kichwa cha malipo cha programu-jalizi.','Checkout Header - Mobile' => 'Kichwa cha Malipo - Simu ya Mkononi','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Onyesha wijeti chini ya kichwa cha malipo cha vifaa vya rununu. Inaonyeshwa tu ikiwa unatumia kichwa cha malipo cha programu-jalizi.','Checkout Sidebar' => 'Upau wa Malipo','Display widgets on the checkout sidebar after the order summary.' => 'Onyesha wijeti kwenye upau wa malipo baada ya muhtasari wa agizo.','Checkout Order Summary' => 'Muhtasari wa Agizo la Malipo','Display widgets inside the order summary at the checkout page.' => 'Onyesha wijeti ndani ya muhtasari wa agizo kwenye ukurasa wa malipo.','Checkout Below Place Order' => 'Angalia Chini ya Weka Agizo','Display widgets below the place order button at the checkout page.' => 'Onyesha wijeti chini ya kitufe cha kuagiza mahali kwenye ukurasa wa malipo.','Checkout Footer' => 'Checkout Footer','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Onyesha wijeti kwenye kijachini cha malipo. Inaonyeshwa tu ikiwa unatumia kijachini cha malipo ya programu-jalizi.','Classic' => 'Classic','Boxed' => 'Imewekwa kwenye sanduku','Split' => 'Gawanya','Minimalist' => 'Minimalist','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Malipo ya Majimaji na Programu jalizi za Tarehe ya Kutuma na CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Tuligundua kuwa unatumia programu jalizi Muda wa Kutuma &amp; Tarehe ya Kuchukua kwa WooCommerce (bila malipo na PRO) na CodeRockz. Kuunganishwa na programu-jalizi hizi kumehamishwa hadi Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Pata toleo jipya la PRO','Fluid Checkout database updated successfully' => 'Hifadhidata ya Malipo ya Maji imesasishwa kwa mafanikio','The database changes where applied successfully.' => 'Hifadhidata inabadilika inapotumika kwa mafanikio.','Dismiss' => 'Ondoa','Fluid Checkout database update' => 'Usasishaji wa hifadhidata ya Malipo ya Maji','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Baadhi ya mabadiliko kwenye hifadhidata yanahitajika. Kama ilivyo kwa sasisho lolote, tunapendekeza <strong>uchukue nakala kamili ya tovuti yako kabla ya kuendelea</strong> .','Update database' => 'Sasisha hifadhidata','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Malipo ya Maji hayaoani na mpangilio wa malipo wa Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Malipo ya Majimaji yanahitaji fomu ya malipo ya msingi ya njia fupi ya WooCommerce ili kufanya kazi. Unapotumia Divi Builder kubinafsisha mwonekano na mwonekano wa ukurasa wa kulipa, misimbo fupi ya kawaida hubadilishwa na wijeti maalum kutoka kwa Divi Builder kwa kila sehemu ya ukurasa wa malipo. Wijeti hizi maalum hazioani na Malipo ya Maji.</p><p> Tafadhali hariri ukurasa wako wa kulipa ukibadilisha wijeti za Divi Builder kwa wijeti ya maandishi iliyo na msimbo mkato <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'Hariri ukurasa wa malipo','Read the documentation.' => 'Soma nyaraka.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Kipengele cha kulipa kwa hatua nyingi cha Kijerumani cha PRO kinahitaji kuzimwa unapotumia Malipo ya Maji','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Unapotumia Fluid Checkout, kipengele cha hatua nyingi kutoka kwa programu-jalizi ya Germanized PRO huwa si lazima na kinaweza kusababisha <strong>hitilafu kubwa wakati wa kuchakata maagizo mapya</strong> . Tafadhali zima kipengele cha Malipo cha hatua nyingi cha Germanized PRO katika mipangilio ya programu-jalizi.','Go to Germanized settings' => 'Nenda kwa mipangilio ya Kijerumani','Thanks for choosing Fluid Checkout!' => 'Asante kwa kuchagua Malipo ya Maji!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Umekuwa ukitumia programu-jalizi kwa muda sasa. Unapendaje hadi sasa?<br> Tafadhali tupe ukadiriaji wa haraka, tunathamini kila maoni na inatuhimiza kuendelea kuboresha programu-jalizi :)','Rate the plugin' => 'Kadiria programu-jalizi','I need help!' => 'Nahitaji msaada!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Baadhi ya vipengele vya Meneja wa Malipo wa WooCommerce na Quadlayers huenda visifanye kazi kama inavyotarajiwa wakati wa kuitumia kwa Malipo ya Maji. Soma <a href="%s">hati zetu</a> kwa habari zaidi na suluhisho mbadala.','Read documentation' => 'Soma nyaraka','Don\'t show this again' => 'Usionyeshe hii tena','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Violezo zaidi vya kubuni','Optimized cart page' => 'Ukurasa wa rukwama ulioboreshwa','Optimized order received / thank you page' => 'Agizo lililoboreshwa limepokelewa / ukurasa wa asante','Edit cart contents at checkout page' => 'Hariri yaliyomo kwenye rukwama kwenye ukurasa wa malipo','Account matching / user matching' => 'Ulinganishaji wa akaunti / ulinganishaji wa mtumiaji','Trust symbols on the cart and thank you pages' => 'Alama za uaminifu kwenye rukwama na kurasa za asante','More positions for the coupon code on the checkout page' => 'Nafasi zaidi za msimbo wa kuponi kwenye ukurasa wa malipo','International phone numbers' => 'Nambari za simu za kimataifa','Gift messages and packing slips' => 'Ujumbe wa zawadi na karatasi za kufunga','Local pickup and in-store collection' => 'Mkusanyiko wa eneo na mkusanyo wa dukani','EU-VAT Assistant' => 'Msaidizi wa EU-VAT','I already have it – Hide this offer' => 'Tayari ninayo - Ficha ofa hii','Activated' => 'Imewashwa','Address book' => 'Kitabu cha anwani','Select an image' => 'Chagua picha','Cart layout' => 'Mpangilio wa gari','Cart optimizations' => 'Uboreshaji wa mikokoteni','Enable cart page optimizations' => 'Washa uboreshaji wa ukurasa wa rukwama','Header and footer template' => 'Kiolezo cha kichwa na kijachini','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Hudhibiti iwapo itatumia kichwa na kijachini cha ukurasa usio na usumbufu au kuweka kichwa na kijachini cha mandhari amilifu kwa sasa.','Distraction free header and footer' => 'Kichwa na kijachini kisicho na usumbufu','Theme\'s header and footer' => 'Kijajuu na kijachini cha mandhari','Cart elements' => 'Vipengele vya gari','Make the order summary stay visible on the cart page while scrolling' => 'Fanya muhtasari wa agizo uendelee kuonekana kwenye ukurasa wa rukwama huku unasogeza','Coupon codes' => 'Misimbo ya kuponi','Hidden' => 'Imefichwa','Before the cart items section' => 'Kabla ya sehemu ya vitu vya gari','Inside the cart items section' => 'Ndani ya sehemu ya vitu vya gari','After the cart items section' => 'Baada ya sehemu ya vitu vya gari','Before the shipping section' => 'Kabla ya sehemu ya usafirishaji','After the shipping section' => 'Baada ya sehemu ya usafirishaji','Before the order summary' => 'Kabla ya muhtasari wa agizo','Inside the order summary' => 'Ndani ya muhtasari wa agizo','Before the order totals' => 'Kabla ya jumla ya agizo','After the order totals' => 'Baada ya jumla ya agizo','After the order summary' => 'Baada ya muhtasari wa agizo','Shipping' => 'Usafirishaji','Select position where to display the shipping costs and calculator on the cart page.' => 'Chagua mahali pa kuonyesha gharama za usafirishaji na kikokotoo kwenye ukurasa wa rukwama.','Display as a cart section' => 'Onyesha kama sehemu ya rukwama','Cross-sells' => 'Mtambuka','Select position where to display the cross-sells section on the cart page.' => 'Chagua mahali pa kuonyesha sehemu ya kuuza bidhaa tofauti kwenye ukurasa wa rukwama.','Before the cart actions' => 'Kabla ya vitendo vya gari','After the cart actions' => 'Baada ya vitendo vya gari','Layout of cross-sell items on the cart page.' => 'Mpangilio wa bidhaa zinazouzwa kwa njia tofauti kwenye ukurasa wa rukwama.','Optimized horizontal cross-sells layout' => 'Muundo ulioboreshwa wa mauzo mtambuka','Theme\'s cross-sells layout' => 'Mpangilio wa mada mtambuka','Number of cross-sell items to display on the cart page' => 'Idadi ya bidhaa zinazouzwa kwa njia tofauti za kuonyesha kwenye ukurasa wa rukwama','Add widget areas to the cart page' => 'Ongeza maeneo ya wijeti kwenye ukurasa wa rukwama','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Maeneo haya ya wijeti hutumiwa kuongeza alama za uaminifu na beji za uaminifu kwenye ukurasa wa rukwama.','Checkout' => 'Lipa','Checkout layout' => 'Mpangilio wa Malipo','Design template' => 'Kiolezo cha kubuni','Dark mode' => 'Hali ya giza','Enable dark mode' => 'Washa hali ya giza','Logo image' => 'Picha ya nembo','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Chagua picha ya kuonyeshwa kwenye kichwa cha ukurasa wa malipo. Inatumika tu wakati wa kutumia kichwa na kijachini kisicho na usumbufu.','Header background color' => 'Rangi ya mandharinyuma ya kichwa','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Chagua rangi ya usuli kwa kichwa cha ukurasa wa malipo. Inatumika tu wakati wa kutumia kichwa na kijachini kisicho na usumbufu.','HTML color value. ie: #f3f3f3' => 'Thamani ya rangi ya HTML. yaani: #f3f3f3','Page background color' => 'Rangi ya mandharinyuma ya ukurasa','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Chagua rangi ya mandharinyuma ya ukurasa wa malipo. Rangi hutumiwa kwa kipengele <em>cha mwili</em> .','Footer background color' => 'Rangi ya mandharinyuma ya kijachini','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Chagua rangi ya usuli kwa kijachini cha ukurasa wa malipo. Inatumika tu wakati wa kutumia kichwa na kijachini kisicho na usumbufu.','Progress bar' => 'Upau wa maendeleo','Display the checkout progress bar when using multi-step checkout layout' => 'Onyesha upau wa malipo unapotumia mpangilio wa hatua nyingi wa kulipa','Make the checkout progress bar stay visible while scrolling' => 'Fanya upau wa maendeleo ya malipo uendelee kuonekana wakati wa kusogeza','Express checkout' => 'Malipo ya haraka','Enable the express checkout section' => 'Washa sehemu ya malipo ya haraka','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Huonyesha sehemu ya malipo ya haraka wakati wa kulipa wakati lango la malipo linalotumika limewashwa kipengele hiki.','Display express checkout buttons in one line for larger screens' => 'Onyesha vitufe vya kulipa katika mstari mmoja kwa skrini kubwa zaidi','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Puuza sehemu za ziada za kulipa unapolipa kwa kutumia lango la malipo linalooana la kulipa','Make the order summary stay visible while scrolling' => 'Fanya muhtasari wa agizo uendelee kuonekana wakati wa kusogeza','Choose a background color for the order summary section.' => 'Chagua rangi ya usuli kwa sehemu ya muhtasari wa agizo.','Highlight the order totals row in the order summary table' => 'Angazia jumla ya safu mlalo katika jedwali la muhtasari wa mpangilio','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Inafaa zaidi wakati sehemu ya muhtasari wa agizo haina rangi ya mandharinyuma iliyoangaziwa. Inaweza pia kutumika kwa Rukwama, Agizo Lililopokelewa na Kuangalia kurasa za Agizo unapotumia Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Kiungo cha kitendo kwenye muhtasari wa agizo wakati wa kulipa.','Edit cart link' => 'Badilisha kiungo cha rukwama','Cart items count' => 'Hesabu ya vitu vya gari','Link to shop page' => 'Unganisha kwa ukurasa wa duka','Cart items' => 'Vitu vya gari','Hide cart items errors at the checkout page' => 'Ficha hitilafu za vipengee vya rukwama kwenye ukurasa wa malipo','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Usionyeshe ujumbe wa makosa ya vipengee vya rukwama juu ya ukurasa wa malipo. Wakati wa kuwasilisha fomu ya kulipa ili kukamilisha ununuzi, ujumbe huu wa hitilafu utaonyeshwa kila wakati.','Place order' => 'Weka agizo','Define the position to display "Place order" and terms checkbox section.' => 'Bainisha nafasi ya kuonyesha &quot;Weka mpangilio&quot; na sehemu ya kisanduku cha kuteua maneno.','Some options might not be compatible with some plugins and themes.' => 'Baadhi ya chaguo huenda zisioanishwe na baadhi ya programu-jalizi na mandhari.','Below the payment section' => 'Chini ya sehemu ya malipo','Below the order summary' => 'Chini ya muhtasari wa agizo','Both below the payment section and the order summary' => 'Zote mbili chini ya sehemu ya malipo na muhtasari wa agizo','Add widget areas to the checkout page' => 'Ongeza maeneo ya wijeti kwenye ukurasa wa malipo','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Maeneo haya ya wijeti hutumiwa kuongeza alama za uaminifu na beji za uaminifu kwenye ukurasa wa malipo.','Display the coupon codes section title' => 'Onyesha kichwa cha sehemu ya misimbo ya kuponi','Select position where to display the coupon codes section on the checkout page.' => 'Chagua mahali pa kuonyesha sehemu ya misimbo ya kuponi kwenye ukurasa wa kulipa.','Before the checkout steps' => 'Kabla ya hatua za malipo','As a substep before payment methods' => 'Kama hatua ndogo kabla ya njia za malipo','As a substep after payment methods' => 'Kama hatua ndogo baada ya njia za malipo','Default button style' => 'Mtindo wa kitufe chaguo-msingi','"Add" link button' => 'Kitufe cha kiungo &quot;Ongeza&quot;.','Checkout fields' => 'Sehemu za malipo','Optional fields' => 'Sehemu za hiari','Hide optional fields behind a link button' => 'Ficha sehemu za hiari nyuma ya kitufe cha kiungo','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Inapendekezwa kuweka chaguo hili kuangaliwa ili kupunguza idadi ya maeneo ya pembejeo wazi, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">soma utafiti</a> .','Do not hide "Address line 2" fields behind a link button' => 'Usifiche sehemu za &quot;Anwani ya 2&quot; nyuma ya kitufe cha kiungo','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Inapendekezwa tu wakati wateja wengi wanahitaji sehemu ya &quot;Anwani ya 2&quot;, au wakati wa kupata anwani sahihi ya usafirishaji ni muhimu (yaani, ikiwa unaleta chakula na bidhaa zingine zinazoharibika).','Billing address' => 'Anwani ya bili','Select position where to display the billing address section on the checkout page.' => 'Chagua mahali pa kuonyesha sehemu ya anwani ya kutuma bili kwenye ukurasa wa malipo.','As a step before shipping' => 'Kama hatua kabla ya kusafirisha','As a sub-step before the shipping address section' => 'Kama hatua ndogo kabla ya sehemu ya anwani ya usafirishaji','As a sub-step after the shipping address section' => 'Kama hatua ndogo baada ya sehemu ya anwani ya usafirishaji','As a step after shipping' => 'Kama hatua baada ya kusafirisha','As a sub-step before the payment section' => 'Kama hatua ndogo kabla ya sehemu ya malipo','Force billing and shipping addresses to the same (single section)' => 'Lazimisha anwani za bili na usafirishaji kwa sehemu moja (sehemu moja)','Checkbox for "Same as shipping/billing address" checked by default' => 'Kisanduku cha kuteua cha &quot;Sawa na anwani ya usafirishaji/ya kutuma bili&quot; kimechaguliwa kwa chaguomsingi','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Kisanduku cha kuteua &quot;Sawa na anwani ya mahali bidhaa zitakapopelekwa&quot; kitaanza kama ilivyoteuliwa kwa chaguomsingi wakati sehemu ya anwani ya usafirishaji itaonyeshwa kwanza.<br> Kisanduku cha kuteua &quot;Sawa na anwani ya kutuma bili&quot; kitaanza kama ilivyochaguliwa kwa chaguo-msingi wakati sehemu ya anwani ya bili itaonyeshwa kwanza.<br> Inapendekezwa kuacha chaguo hili likikaguliwa ili kupunguza kwa kiasi kikubwa idadi ya sehemu zilizo wazi za uingizaji wakati wa kulipa, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">soma utafiti</a> .','Highlight the billing address section in the checkout form' => 'Angazia sehemu ya anwani ya kutuma bili katika fomu ya kulipa','Shipping address' => 'Anwani ya usafirishaji','Highlight the shipping address section in the checkout form' => 'Angazia sehemu ya anwani ya usafirishaji katika fomu ya malipo','Shipping methods' => 'Mbinu za usafirishaji','Choose in which position to display the shipping methods section.' => 'Chagua katika nafasi gani ya kuonyesha sehemu ya njia za usafirishaji.','Before shipping address' => 'Kabla ya anwani ya usafirishaji','After shipping address' => 'Baada ya anwani ya usafirishaji','Local pickup' => 'Uchukuzi wa ndani','Removes shipping address section when a local pickup shipping method is selected.' => 'Huondoa sehemu ya anwani ya usafirishaji wakati mbinu ya usafirishaji ya mahali ulipo imechaguliwa.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Hubadilisha anwani ya usafirishaji na mahali pa kuchukua wakati njia ya usafirishaji ya karibu imechaguliwa.','Choose which address to save as the shipping address for local pickup orders.' => 'Chagua anwani ya kuhifadhi kama anwani ya usafirishaji kwa maagizo ya karibu ya kuchukua.','Save the selected pickup location' => 'Hifadhi eneo lililochaguliwa la kuchukua','Save same as the billing address' => 'Hifadhi sawa na anwani ya kutuma bili','Do not save any shipping address' => 'Usihifadhi anwani yoyote ya usafirishaji','Company name field for shipping address' => 'Sehemu ya jina la kampuni kwa anwani ya usafirishaji','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Badilisha mwonekano wa sehemu ya jina la kampuni kwa sehemu ya anwani ya usafirishaji kwenye fomu ya kulipa.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Ikiwa sehemu itawekwa kama &quot;hiari&quot;, ambayo ni hali chaguomsingi ya mwonekano, hakuna mabadiliko yatatumika ili kuruhusu programu-jalizi zingine kutekeleza mabadiliko yoyote wanayohitaji.','Hidden (remove field)' => 'Imefichwa (ondoa sehemu)','Optional' => 'Hiari','Required' => 'Inahitajika','Add shipping phone field to the checkout form.' => 'Ongeza sehemu ya simu ya usafirishaji kwenye fomu ya kulipa.','Choose in which step to display the shipping phone field.' => 'Chagua katika hatua gani ya kuonyesha sehemu ya simu ya usafirishaji.','Contact step' => 'Hatua ya mawasiliano','Billing phone' => 'Simu ya malipo','Add billing phone field to the checkout form.' => 'Ongeza sehemu ya simu ya bili kwenye fomu ya kulipa.','Choose in which step to display the billing phone field.' => 'Chagua katika hatua gani ya kuonyesha sehemu ya simu ya bili.','Show country code beside the flag' => 'Onyesha msimbo wa nchi kando ya bendera','Show an example of a valid phone number inside phone fields' => 'Onyesha mfano wa nambari halali ya simu ndani ya sehemu za simu','Do not change placeholders' => 'Usibadilishe vishika nafasi','Show if not defined' => 'Onyesha ikiwa haijafafanuliwa','Always show' => 'Onyesha kila wakati','Order notes' => 'Agiza maelezo','Define the visibility of the additional order notes field.' => 'Bainisha mwonekano wa sehemu ya vidokezo vya agizo la ziada.','Gift options' => 'Chaguzi za zawadi','Allow customers to add a gift message and other gift related options to the order.' => 'Ruhusu wateja waongeze ujumbe wa zawadi na chaguo zingine zinazohusiana na zawadi kwenye agizo.','Display the gift message as part of the order details table instead of a separate section' => 'Onyesha ujumbe wa zawadi kama sehemu ya jedwali la maelezo ya agizo badala ya sehemu tofauti','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Chaguo hili linaathiri ukurasa wa uthibitishaji wa agizo (ukurasa wa asante) na uagize maelezo kwenye kurasa za akaunti, barua pepe na hati za kufunga.','Account matching' => 'Kulinganisha akaunti','Enable the account matching feature' => 'Washa kipengele cha kulinganisha akaunti','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Husisha maagizo ya mteja aliyealikwa na akaunti yake iliyopo wakati tayari kuna akaunti na maelezo ya mawasiliano ya mteja.','Display message when an account exists with the email address provided' => 'Onyesha ujumbe wakati akaunti ipo na anwani ya barua pepe iliyotolewa','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Hubadilisha sehemu za kuunda akaunti kwa arifa na chaguo la kuingia. Katika baadhi ya miktadha, inaweza kupendekezwa kuacha chaguo hili likiwa limezimwa ili kulinda faragha ya wateja.','Dashboard' => 'Dashibodi','Integrations' => 'Ushirikiano','License keys' => 'Vifunguo vya leseni','Visit our website for more information about our plugins and add-ons.' => 'Tembelea tovuti yetu kwa habari zaidi kuhusu programu-jalizi zetu na nyongeza.','Order pay page' => 'Agiza ukurasa wa malipo','Order pay' => 'Malipo ya agizo','Enable order pay page optimizations' => 'Washa uboreshaji wa ukurasa wa malipo ya agizo','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Hubadilisha mpangilio wa ukurasa wa malipo ya agizo kwa maagizo yaliyopo yanayosubiri malipo kutoka kwa mteja.','Add widget areas to the order pay page' => 'Ongeza maeneo ya wijeti kwenye ukurasa wa malipo wa agizo','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Maeneo haya ya wijeti hutumiwa kuongeza alama za uaminifu na beji za uaminifu kwenye ukurasa wa malipo wa agizo.','Thank you page & order details layout' => 'Asante ukurasa na mpangilio wa maelezo','Order details optimizations' => 'Uboreshaji wa maelezo ya agizo','Enable thank you page and order details optimizations' => 'Washa ukurasa wa asante na uagize uboreshaji wa maelezo','Changes the layout of order details on the thank you page and account pages.' => 'Hubadilisha mpangilio wa maelezo ya agizo kwenye ukurasa wa asante na kurasa za akaunti.','Enable order details customizations on email notifications' => 'Washa ubinafsishaji wa maelezo ya agizo kwenye arifa za barua pepe','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Onyesha sehemu mpya na ubadilishe mpangilio wa sehemu kwenye arifa za barua pepe. Mitindo ya maelezo ya agizo kwenye arifa za barua pepe bado haijabadilika.','Thank you page' => 'Asante ukurasa','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Chaguo hizi huathiri ukurasa wa asante, unaojulikana pia kama kurasa za uthibitishaji wa agizo au agizo.','Order details layout' => 'Mpangilio wa maelezo ya agizo','Display the order details with wide layout on the thank you page' => 'Onyesha maelezo ya agizo kwa mpangilio mpana kwenye ukurasa wa asante','Add widget areas to the thank you page' => 'Ongeza maeneo ya wijeti kwenye ukurasa wa asante','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Maeneo haya ya wijeti hutumiwa kuongeza alama za uaminifu na beji za uaminifu kwenye ukurasa wa asante.','Order actions' => 'Agiza vitendo','Choose in which position to display the order actions.' => 'Chagua katika nafasi gani ya kuonyesha vitendo vya mpangilio.','Inside the order overview' => 'Ndani ya muhtasari wa agizo','After the order overview' => 'Baada ya muhtasari wa agizo','After order sections' => 'Baada ya sehemu za kuagiza','Order status' => 'Hali ya agizo','Display the order status progress bar' => 'Onyesha upau wa maendeleo ya hali ya agizo','Choose in which position to display the section.' => 'Chagua katika nafasi gani ya kuonyesha sehemu.','After the order overview and payment instructions' => 'Baada ya muhtasari wa agizo na maagizo ya malipo','Before the order items section' => 'Kabla ya sehemu ya vitu vya kuagiza','Inside the order items section' => 'Ndani ya sehemu ya vitu vya kuagiza','After the order items section' => 'Baada ya sehemu ya vitu vya kuagiza','On the sidebar' => 'Kwenye upau wa pembeni','Order downloads' => 'Agiza vipakuliwa','Gift message' => 'Ujumbe wa zawadi','Tools' => 'Zana','Troubleshooting' => 'Kutatua matatizo','Debug options' => 'Chaguzi za utatuzi','Debug mode' => 'Hali ya utatuzi','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Kutumia hali ya utatuzi huathiri utendaji wa tovuti. Tumia chaguo hili pekee unapotatua matatizo.','Load unminified assets' => 'Pakia mali isiyopunguzwa','Enhanced select fields' => 'Uga zilizoimarishwa','Fix automatic zoom-in on form fields' => 'Rekebisha kuvuta kiotomatiki kwenye sehemu za fomu','Set <code>font-size</code> inside form fields to 16px' => 'Weka <code>font-size</code> ndani ya sehemu za fomu kuwa 16px','Fluid Checkout' => 'Malipo ya Majimaji','Settings' => 'Mipangilio','Support' => 'Msaada','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Pata toleo jipya la PRO</a> ili kufungua chaguo zaidi.','(PRO)' => '(PRO)','(experimental)' => '(majaribio)','Please verify your phone number.' => 'Tafadhali thibitisha nambari yako ya simu.','The Bluehost Plugin' => 'Programu-jalizi ya Bluehost','Custom fields' => 'Sehemu maalum','Enable custom shipping email field' => 'Washa sehemu ya barua pepe maalum ya usafirishaji','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Ikiwezeshwa, sehemu ya barua pepe ya usafirishaji kutoka kwa programu-jalizi ya Bluehost itaongezwa kwenye fomu ya kulipa.','Captcha Pro by BestWebSoft' => 'Captcha Pro na BestWebSoft','Captcha position' => 'Nafasi ya Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Fafanua nafasi ya kuonyesha sehemu ya captcha. Baadhi ya nafasi zinaweza zisifanye kazi kulingana na aina ya captcha iliyochaguliwa.','Selecting a pickup point is required before proceeding.' => 'Inahitajika kuchagua mahali pa kuchukua kabla ya kuendelea.','Pickup point' => 'Sehemu ya kuchukua','Pickup point not selected yet.' => 'Eneo la kuchukua bado halijachaguliwa.','Pickup point:' => 'Mahali pa kuchukua:','Mailchimp for WooCommerce' => 'Mailchimp kwa WooCommerce','Subscribe checkbox' => 'Jisajili kisanduku tiki','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Batilisha nafasi ya kisanduku cha kuteua cha kujiandikisha kwenye ukurasa wa malipo na uionyeshe kila wakati kwenye hatua ya mawasiliano','Before Shipping Address' => 'Kabla ya Anwani ya Kusafirisha','(originally "%s")' => '(asili &quot;%s&quot;)','After Shipping Address' => 'Baada ya Anwani ya Usafirishaji','Selecting a collection point is required when shipping with FermoPoint.' => 'Inahitajika kuchagua mahali pa kukusanyia unaposafirisha ukitumia FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Ikiangaliwa hufahamisha typos katika barua pepe kwa watumiaji. (Kipengele hiki kimezimwa kwa sababu Malipo ya Majimaji hutoa kipengele. Mabadiliko ya chaguo hili hayatafanya kazi)','Enable Mail Check: (disabled feature)' => 'Washa Ukaguzi wa Barua: (kipengele kimezimwa)','Carrier:' => 'Mtoa huduma:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - Uuzaji wa Barua pepe wa WooCommerce','Sign up checkbox position' => 'Jisajili nafasi ya kisanduku cha kuteua','Move the sign up checkbox to the contact step' => 'Sogeza kisanduku cha kuteua cha kujisajili hadi kwenye hatua ya mwasiliani','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Ikiwashwa, kisanduku cha kuteua kitahamishwa hadi hatua ya mwasiliani bila ya eneo la kuonyesha lililofafanuliwa katika mipangilio ya programu-jalizi ya Sendinblue.','Theme Betheme' => 'Mandhari ya mandhari','Checkout progress' => 'Maendeleo ya malipo','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Toa sehemu ya hatua za kulipa kutoka kwa Betheme kwenye malipo, rukwama na uagize kurasa zilizopokelewa.','Theme Fennik' => 'Mandhari ya Fennik','Breadcrumbs' => 'Makombo ya mkate','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Toa sehemu ya makombo kutoka kwa mandhari ya Fennik unapotumia kichwa na kijachini cha Fluid Checkout.','Theme Go' => 'Mandhari Nenda','My account layout' => 'Mpangilio wa akaunti yangu','Enable wide layout on "My account" page.' => 'Washa mpangilio mpana kwenye ukurasa wa &quot;Akaunti yangu&quot;.','Theme Impreza' => 'Mandhari Impreza','Header' => 'Kijajuu','Spacing for site header at the checkout page (in pixels)' => 'Nafasi ya kichwa cha tovuti kwenye ukurasa wa malipo (katika pikseli)','Only applicable when using the Impreza theme header at the checkout page.' => 'Inatumika tu unapotumia kichwa cha mandhari ya Impreza kwenye ukurasa wa malipo.','Theme Kapee' => 'Mandhari ya Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Toa sehemu ya hatua za kulipa kutoka kwa mandhari ya Kapee kwenye malipo, rukwama na agiza kurasa zilizopokelewa.','Theme Porto' => 'Mandhari ya Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Toa sehemu ya hatua za kulipa kutoka kwa mandhari ya Porto kwenye malipo, rukwama na uagize kurasa zilizopokewa.','Theme Pressmart' => 'Mada ya Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Toa sehemu ya hatua za kulipa kutoka kwa mandhari ya Pressmart kwenye sehemu ya kulipa, rukwama na uagize kurasa zilizopokewa.','Theme The Gem' => 'Mandhari ya Gem','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Toa sehemu ya hatua za kulipa kutoka kwenye mandhari ya Gem unapotumia kichwa na kijachini cha Malipo ya Maji.','Theme Woodmart' => 'Mandhari ya Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Toa sehemu ya hatua za kulipa kutoka kwa mandhari ya Woodmart unapotumia kichwa na kijachini cha Fluid Checkout.','Checkout options' => 'Chaguzi za malipo','Disable the theme checkout options' => 'Zima chaguo za malipo ya mandhari','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Chaguzi zinazoonyesha picha ya bidhaa, uga wa kiasi, kitufe cha kuondoa na kiungo cha ukurasa wa bidhaa ulioongezwa na mandhari huzimwa kwa chaguomsingi.','Theme Atomion' => 'Mandhari ya Atomi','Order progress' => 'Agizo la maendeleo','Display order progress from the theme' => 'Onyesha maendeleo ya mpangilio kutoka kwa mada','Display the form field labels visible on the page' => 'Onyesha lebo za sehemu za fomu zinazoonekana kwenye ukurasa','It is recommended to keep this option enabled for a better user experience.' => 'Inapendekezwa kuwasha chaguo hili kwa matumizi bora ya mtumiaji.','Theme ZK Nito' => 'Mandhari ZK Nito','Add extra fields to the checkout form' => 'Ongeza sehemu za ziada kwenye fomu ya malipo','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Huongeza barua pepe ya ziada ya usafirishaji na sehemu ya simu ya usafirishaji kwenye sehemu ya anwani ya usafirishaji.','Go to the home page' => 'Nenda kwenye ukurasa wa nyumbani','Skip to content' => 'Ruka hadi yaliyomo','Create an account' => 'Fungua akaunti','Log in to your account' => 'Ingia kwenye akaunti yako','Already have an account?' => 'Je, tayari una akaunti?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Umeingia kama %1$s. <a href="%2$s">Toka nje</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Agizo lako lina jumla ya kiasi kinachodaiwa %s. Hakuna malipo zaidi yanayohitajika.','Close and continue with checkout' => 'Funga na uendelee na malipo','Continue' => 'Endelea','Parcel terminal' => 'Terminal ya sehemu','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Wijeti hii imebadilishwa na Malipo ya Maji.</p><p> Unapotumia Malipo ya Maji, ukurasa wa kulipa unahitaji kutumia njia fupi ya awali ya WooCommerce <code>[woocommerce_checkout]</code> ili kufanya kazi ipasavyo.</p><p> Kwa habari zaidi, tembelea hati za Malipo ya Maji.</p>','Theme The7' => 'Mandhari The7','Additional header sections' => 'Sehemu za ziada za kichwa','Output additional header sections if enabled in the theme settings.' => 'Toa sehemu za kichwa cha ziada ikiwashwa katika mipangilio ya mandhari.','More information' => 'Taarifa zaidi','Pick a Locker' => 'Chagua Locker','Page template' => 'Kiolezo cha ukurasa','Use `Order confirmation` page template for block-based themes' => 'Tumia kiolezo cha ukurasa wa `Uthibitishaji wa Agizo` kwa mandhari yenye msingi wa kuzuia','Only applies when using a block-based theme.' => 'Inatumika tu wakati wa kutumia mandhari yenye msingi wa kizuizi.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Fomu ya malipo','Apply styles to the Stripe payment form fields' => 'Tumia mitindo kwenye sehemu za fomu ya malipo ya Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Ikiwezeshwa, Malipo ya Majimaji yatatumia mitindo iliyoboreshwa ili uoanifu na programu-jalizi. Unaweza kutaka kuzima hii ikiwa unatumia mitindo maalum kwa uga za fomu ya malipo ya Stripe.','Theme Nyture' => 'Mandhari Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Toa sehemu ya hatua za kulipa kutoka kwa mandhari ya Nyture unapotumia Malipo ya Maji.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Huruhusu wateja kufanya malipo ya maagizo ambayo yameundwa na msimamizi wa duka au ambayo hayajakamilika wakati wa kulipa.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Kidhibiti cha Malipo cha WooCommerce na Quadlayers hakiendani na Malipo ya Maji','Company name field for billing address' => 'Sehemu ya jina la kampuni kwa anwani ya bili','Change visibility for the company name field for the billing address section on the checkout form.' => 'Badilisha mwonekano wa sehemu ya jina la kampuni kwa sehemu ya anwani ya kutuma bili kwenye fomu ya kulipa.','Theme Bookshelf' => 'Rafu ya Vitabu ya Mandhari','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Toa sehemu ya hatua za kulipa kutoka kwa mandhari ya Rafu ya Vitabu unapotumia Malipo ya Maji.','Account password' => 'Nenosiri la akaunti','An account will be created with the information provided at checkout when completing the order.' => 'Akaunti itaundwa ikiwa na maelezo yaliyotolewa wakati wa kulipa wakati wa kukamilisha agizo.','Choose the style of the progress bar.' => 'Chagua mtindo wa upau wa maendeleo.','Bars' => 'Baa','Theme Ireca' => 'Mandhari Ireca','WooCommerce page layout' => 'Mpangilio wa ukurasa wa WooCommerce','Force wide layout on WooCommerce pages' => 'Lazimisha mpangilio mpana kwenye kurasa za WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Hii inahakikisha kuwa sehemu ya maudhui si finyu sana kwenye kurasa za WooCommerce ikijumuisha malipo, rukwama, agizo lililopokelewa, malipo ya agizo na kurasa za akaunti.','WooCommerce Smart Coupons' => 'Kuponi za WooCommerce Smart','Position on checkout page' => 'Nafasi kwenye ukurasa wa malipo','Choose where to display the available coupons section on the checkout page.' => 'Chagua mahali pa kuonyesha sehemu ya kuponi zinazopatikana kwenye ukurasa wa malipo.','Before the progress bar' => 'Kabla ya bar ya maendeleo','After the progress bar' => 'Baada ya bar ya maendeleo','Before coupon codes section' => 'Kabla ya sehemu ya misimbo ya kuponi','Format phone numbers according to the rules for each country.' => 'Fomati nambari za simu kulingana na sheria za kila nchi.','Use precise phone number validation' => 'Tumia uthibitishaji sahihi wa nambari ya simu','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Hiki ni kipengele cha majaribio na huenda kisifanye kazi inavyotarajiwa katika usanidi wote. Itumie kwa tahadhari.','Phone number validation types used when precise validation is enabled.' => 'Aina za uthibitishaji wa nambari za simu zinazotumiwa wakati uthibitishaji kwa usahihi umewashwa.','Mobile' => 'Simu ya Mkononi','Fixed line' => 'Mstari usiohamishika','Toll free' => 'Bila malipo','Or' => 'Au','Contact' => 'Mawasiliano','Multi step' => 'Hatua nyingi','2 columns' => 'Safu wima 2','1 column' => 'Safu wima 1','Before checkout steps' => 'Hatua za kabla ya kulipa','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Unapotumia mpangilio wa malipo wa <em>&quot;safu wima 1&quot;</em> chaguo hili huwekwa kila wakati kuwa <em>&quot;Hatua za Kabla ya malipo&quot;</em> na pia hutumika kwa mwonekano wa eneo-kazi.','Position for the extra order summary section on mobile.' => 'Nafasi ya sehemu ya muhtasari wa agizo la ziada kwenye simu.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Chaguo <em>&quot;Kwenye kichwa cha habari cha tovuti&quot;</em> linatumika tu wakati wa kutumia kichwa cha habari kisicho na usumbufu.','On the site header (requires distraction-free header)' => 'Kwenye kichwa cha tovuti (inahitaji kichwa cha habari kisicho na usumbufu)','Initial state for the expansible order summary section on mobile.' => 'Hali ya awali ya sehemu ya muhtasari wa agizo linaloweza kupanuliwa kwenye simu ya mkononi.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Tunapendekeza kuiweka kama <em>iliyopanuliwa</em> kwa nchi zifuatazo kutokana na mahitaji ya udhibiti: <strong>Ujerumani</strong> , <strong>Austria</strong> , <strong>Uswisi</strong> , <strong>Uholanzi</strong> , <strong>Poland</strong> , <strong>Ubelgiji</strong> na <strong>Ufaransa</strong> .','Collapsed' => 'Imekunjwa','Expanded' => 'Imepanuliwa','Do not show' => 'Usionyeshe','yes' => 'ndiyo','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Sehemu ya simu ya usafirishaji inaweza kulazimishwa kama &quot;inahitajika&quot; ikiwa sehemu ya anwani ya bili itaonyeshwa baada ya sehemu ya anwani ya usafirishaji, na sehemu ya simu ya bili imewekwa kama &quot;inahitajika&quot;. Hii inahitajika ili kuhakikisha anwani ya usafirishaji inaweza kunakiliwa hadi kwenye anwani ya bili wakati chaguo hilo linapochaguliwa, vinginevyo mteja anaweza asiweze kujaza fomu ya kulipa.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Sehemu ya simu ya bili inaweza kulazimishwa kama &quot;inahitajika&quot; ikiwa sehemu ya anwani ya bili itaonyeshwa kabla ya sehemu ya anwani ya usafirishaji, na sehemu ya simu ya usafirishaji imewekwa kama &quot;inahitajika&quot;. Hii inahitajika ili kuhakikisha anwani ya usafirishaji inaweza kunakiliwa hadi kwenye anwani ya bili wakati chaguo hilo linapochaguliwa, vinginevyo mteja anaweza asiweze kujaza fomu ya kulipa.','Settings profiles' => 'Wasifu wa mipangilio','Settings profile' => 'Wasifu wa mipangilio','You do not have permission to perform this action.' => 'Huna ruhusa ya kufanya kitendo hiki.','You do not have permission to activate plugins.' => 'Huna ruhusa ya kuamilisha programu-jalizi.','Missing plugin.' => 'Programu-jalizi haipo.','Plugin activated.' => 'Programu-jalizi imewashwa.','The following changes will be applied:' => 'Mabadiliko yafuatayo yatatumika:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Tangu Fluid Checkout 5.0, mipangilio imehifadhiwa tofauti. Chaguzi za zamani bado zimehifadhiwa kwenye hifadhidata ili kuruhusu kushushwa daraja hadi matoleo ya awali ikiwa inahitajika.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Duka lako limekuwa likifanya kazi kwa takriban wiki 2 kwenye mipangilio mipya ili uweze kusafisha chaguo za zamani zilizohifadhiwa kwenye hifadhidata. Tafadhali kumbuka kuwa baada ya kusafisha, ikiwa unahitaji kushusha kiwango hadi matoleo ya awali ya programu-jalizi itatumia thamani chaguo-msingi kwa mipangilio yote.','Fluid Checkout settings cleanup' => 'Usafi wa mipangilio ya Fluid Checkout','Delete leftover options' => 'Futa chaguo zilizobaki','Help us improve Fluid Checkout' => 'Tusaidie kuboresha Malipo ya Maji','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Shiriki ripoti za mazingira ya tovuti bila majina ukitumia Fluid Checkout ili kupata usaidizi wa haraka na kutusaidia kuboresha utangamano na kupima athari. Hakuna data nyeti ya mteja, mtumiaji, au iliyojumuishwa. Unaweza kuchagua kinachoshirikiwa wakati wowote kutoka kwa mipangilio ya Zana.','Enable site environment reports' => 'Washa ripoti za mazingira ya tovuti','Review settings' => 'Mipangilio ya ukaguzi','This preview has expired. Reload the admin page to start a new preview.' => 'Hakikisho hili limekwisha muda wake. Pakia upya ukurasa wa msimamizi ili kuanza hakikisho jipya.','Preview expired' => 'Muda wa kuhakiki umeisha','Orders cannot be placed in the preview.' => 'Maagizo hayawezi kuwekwa katika onyesho la awali.','Logging in is not available in the preview.' => 'Kuingia hakupatikani katika onyesho la kuchungulia.','Accounts cannot be created in the preview.' => 'Akaunti haziwezi kuundwa katika onyesho la kuchungulia.','Requests to other sites are blocked in the preview.' => 'Maombi kwa tovuti zingine yamezuiwa katika onyesho la awali.','Processing…' => 'Inachakata…','Something went wrong. Please try again.' => 'Kuna kitu kimeenda vibaya. Tafadhali jaribu tena.','Activate plugin' => 'Washa programu-jalizi','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Kifurushi kamili cha malipo','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Vipengele vyote vya PRO + nyongeza zote, bei moja. Violezo vya muundo, kikapu kilichoboreshwa na kuagiza kurasa zilizopokelewa, ulinganishaji wa akaunti, na mengine mengi.','Optimized order pay page' => 'Ukurasa wa malipo wa agizo ulioboreshwa','Express checkout buttons from supported payment methods' => 'Vifungo vya malipo kutoka kwa njia za malipo zinazoungwa mkono','Delayed account creation' => 'Kuchelewa kwa uundaji wa akaunti','Address autocomplete with Google Maps APIs' => 'Kukamilisha anwani kiotomatiki kwa kutumia API za Ramani za Google','Multiple saved addresses with the address book' => 'Anwani nyingi zilizohifadhiwa na kitabu cha anwani','EU-VAT assistant' => 'Msaidizi wa EU-VAT','Hide this section' => 'Ficha sehemu hii','Learn more' => 'Pata maelezo zaidi','Get early access' => 'Pata ufikiaji wa mapema','Activate add-on' => 'Washa programu jalizi','Get more out of your checkout journey' => 'Pata faida zaidi kutokana na safari yako ya kulipa','Test API key' => 'Ufunguo wa API ya jaribio','Guided setup' => 'Usanidi unaoongozwa','Options' => 'Chaguzi','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Weka mpangilio na muundo kwenye <a href="%s">chaguo za kulipa</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Washa malipo ya wageni na/au kagua <a href="%s">mipangilio ya akaunti za wateja</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Washa <a href="%1$s">kikapu</a> kilichoboreshwa, <a href="%2$s">asante</a> na <a href="%3$s">uagize kurasa za malipo</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Washa <a href="%s">kukamilisha anwani kiotomatiki</a> kutoka Ramani za Google.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Washa anwani nyingi zilizohifadhiwa ukitumia <a href="%s">kitabu cha anwani</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Angalia kama kuna <a href="%s">chaguo zozote za ujumuishaji</a> zinazopatikana kwa mandhari au programu-jalizi zingine ulizosakinisha.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Pata usaidizi wa haraka na utusaidie kuboresha utangamano na kupima athari. <a href="%s">Washa ufuatiliaji wa matumizi</a> kutoka kwa mipangilio ya zana.','Missing settings tab.' => 'Kichupo cha mipangilio hakipo.','Getting started' => 'Kuanza','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Sawa! Ukurasa wako wa malipo sasa unafanya kazi kwenye Fluid Checkout.</strong> Hapa kuna hatua chache za kuanza:','Completed' => 'Imekamilika','Preview report data' => 'Hakiki data ya ripoti','Send now' => 'Tuma sasa','Auto-detect' => 'Gundua kiotomatiki','Afrikaans' => 'Kiafrikana','Albanian' => 'Kialbania','Amharic' => 'Kiamhariki','Arabic' => 'Kiarabu','Armenian' => 'Kiarmenia','Azerbaijani' => 'Kiazabajani','Basque' => 'Kibasque','Belarusian' => 'Kibelarusi','Bengali' => 'Kibengali','Bosnian' => 'Kibosnia','Bulgarian' => 'Kibulgaria','Burmese' => 'Kiburma','Catalan' => 'Kikatalani','Chinese' => 'Kichina','Chinese (Simplified)' => 'Kichina (Kilichorahisishwa)','Chinese (Hong Kong)' => 'Kichina (Hong Kong)','Chinese (Traditional)' => 'Kichina (Cha Jadi)','Croatian' => 'Kikroeshia','Czech' => 'Kicheki','Danish' => 'Kidenmaki','Dutch' => 'Kiholanzi','English' => 'Kiingereza','English (Australian)' => 'Kiingereza (Kiaustralia)','English (Great Britain)' => 'Kiingereza (Uingereza)','Estonian' => 'Kiestonia','Farsi' => 'Kifarsi','Finnish' => 'Kifini','Filipino' => 'Kifilipino','French' => 'Kifaransa','French (Canadian)' => 'Kifaransa (Kanada)','Galician' => 'Kigalisia','Georgian' => 'Kijojia','German' => 'Kijerumani','Greek' => 'Kigiriki','Gujarati' => 'Kigujarati','Hebrew' => 'Kiebrania','Hindi' => 'Kihindi','Hungarian' => 'Kihungaria','Icelandic' => 'Kiaisilandi','Indonesian' => 'Kiindonesia','Italian' => 'Kiitaliano','Japanese' => 'Kijapani','Kannada' => 'Kikannada','Kazakh' => 'Kikazakh','Khmer' => 'Kikhmer','Korean' => 'Kikorea','Kyrgyz' => 'Kyrgyz','Lao' => 'Kilao','Latvian' => 'Kilatvia','Lithuanian' => 'Kilithuania','Macedonian' => 'Kimasedonia','Malay' => 'Kimalei','Malayalam' => 'Kimalayalam','Marathi' => 'Kimarathi','Mongolian' => 'Kimongolia','Nepali' => 'Kinepali','Norwegian' => 'Kinorwe','Polish' => 'Kipolandi','Portuguese' => 'Kireno','Portuguese (Brazil)' => 'Kireno (Brazili)','Portuguese (Portugal)' => 'Kireno (Ureno)','Punjabi' => 'Kipunjabi','Romanian' => 'Kiromania','Russian' => 'Kirusi','Serbian' => 'Kiserbia','Sinhalese' => 'Kisinhali','Slovak' => 'Kislovakia','Slovenian' => 'Kislovenia','Spanish' => 'Kihispania','Spanish (Latin America)' => 'Kihispania (Amerika ya Kilatini)','Swahili' => 'Kiswahili','Swedish' => 'Kiswidi','Tamil' => 'Kitamil','Telugu' => 'Kitelugu','Thai' => 'Kithai','Turkish' => 'Kituruki','Ukrainian' => 'Kiukreni','Urdu' => 'Kiurdu','Vietnamese' => 'Kivietnam','Zulu' => 'Kizulu','Google address autocomplete' => 'Kukamilisha kiotomatiki kwa anwani ya Google','Google Places API version' => 'Toleo la API ya Google Places','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Chagua toleo gani la API ya Google Places la kutumia. Tunapendekeza uhamie kwenye API mpya ya Places haraka iwezekanavyo.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Tunapendekeza kutumia &quot;Places API (Mpya)&quot; kuanzia Machi 1, 2025, Google itahamisha toleo la &quot;Places API (Legacy)&quot; hadi hali ya Legacy, ikimaanisha hutaweza tena kuwezesha huduma hii kwa funguo mpya za API na kwamba toleo hilo la API hatimaye halitapatikana tena. Akaunti zilizopo tayari zinazotumia Legacy API zinaweza kuendelea kufanya kazi bila usumbufu.','(Recommended)' => '(Inapendekezwa)','Google API key' => 'Ufunguo wa API ya Google','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Bandika ufunguo wako wa Google API na utumie kitufe cha majaribio ili kuthibitisha kuwa unafanya kazi kwa tovuti hii. Hakikisha ufunguo ni halali na unaruhusiwa kwa kikoa chako, vinginevyo sehemu ya anwani inaweza kuzuiwa na kuwazuia wateja kukamilisha maagizo yao.','Enable Google address autocomplete' => 'Washa ukamilishaji otomatiki wa anwani ya Google','Enable address autocompletion using the Google Maps APIs.' => 'Washa ukamilishaji kiotomatiki wa anwani kwa kutumia API za Ramani za Google.','Google API language' => 'Lugha ya API ya Google','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Lugha hii itatumika kuonyesha mapendekezo ya anwani za Google Places API na anwani pia zitakamilika kiotomatiki katika lugha hii.','Result types' => 'Aina za matokeo','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Acha tupu ili kukubali aina yoyote ya matokeo, ambayo kwa kawaida hutoa matokeo bora zaidi ya ulinganifu. <a href="%s" target="_blank">Tazama hati kwa maelezo zaidi</a> .<br> Chagua hadi aina 5 za matokeo ya utafutaji wa anwani ili urudishe kwenye sehemu za kukamilisha kiotomatiki anwani.<br> Tembelea hati za Ramani za Google ili upate maelezo zaidi kuhusu <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">aina zinazoungwa mkono</a> .','Result types (Legacy API)' => 'Aina za matokeo (API ya Urithi)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Ni aina gani ya matokeo ya utafutaji wa anwani ya kurudi unapotumia Places API (Legacy).<br> Tembelea hati za API ya Maeneo ya Google Iliyopitwa na Wakati ili ujifunze zaidi kuhusu <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">aina zinazoungwa mkono</a> .','Company fields' => 'Sehemu za kampuni','Enable autocomplete for the company name if available' => 'Washa kipengele cha kukamilisha kiotomatiki kwa jina la kampuni ikiwa kinapatikana','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Wezesha ukamilishaji otomatiki wa sehemu ya kampuni ukitumia taarifa ya jina la kampuni inaporudishwa kutoka kwa API za Ramani za Google.','Business search' => 'Utafutaji wa biashara','Enable search for businesses in the company field' => 'Wezesha utafutaji wa biashara katika uwanja wa kampuni','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Washa mapendekezo ya anwani zinazohusiana na biashara unapoandika kwenye sehemu ya kampuni, kisha jaza kiotomatiki sehemu zote za anwani wakati biashara imechaguliwa kutoka kwa mapendekezo.','Company result types' => 'Aina za matokeo ya kampuni','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Chagua hadi aina 5 za matokeo ya utafutaji wa anwani ili urudi kwenye sehemu za kampuni zinazokamilisha kiotomatiki.<br> Thamani inayopendekezwa ni <code>establishment</code> , ambao unajumuisha aina nyingi za biashara.<br> Acha tupu ili kukubali aina yoyote ya matokeo, ikiwa ni pamoja na matokeo ambayo hayahusiani na biashara.<br> Tembelea hati za Ramani za Google ili upate maelezo zaidi kuhusu <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">aina zinazoungwa mkono</a> .','Google logo' => 'Nembo ya Google','Show text and logo "Powered by Google"' => 'Onyesha maandishi na nembo &quot;Inaendeshwa na Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Ikichaguliwa, maandishi na nembo &quot;Inaendeshwa na Google&quot; itaonyeshwa chini ya kisanduku cha mapendekezo ya kukamilisha anwani kiotomatiki.','Brasil API address autocomplete' => 'Kukamilisha kiotomatiki anwani ya API ya Brazil','Brasil API' => 'API ya Brazil','Enable Brasil API address autocomplete for CEP fields' => 'Washa ukamilishaji otomatiki wa anwani ya API ya Brasil kwa sehemu za CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Tumia API ya Brasil ili kupata na kujaza anwani kiotomatiki kwa kutumia sehemu ya CEP/Postcode. Inafaa tu kwa anwani za Brazil.','API version' => 'Toleo la API','Choose which version of the Brasil API CEP method to use.' => 'Chagua toleo gani la mbinu ya Brasil API CEP la kutumia.','Address book migration' => 'Uhamiaji wa kitabu cha anwani','WooCommerce addresses' => 'Anwani za WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Nakili anwani zilizopo za usafirishaji na bili kutoka WooCommerce kwenye kitabu cha anwani cha wateja.','Enable the address book feature' => 'Washa kipengele cha kitabu cha anwani','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Waruhusu wateja kuhifadhi anwani nyingi na kufafanua anwani chaguo-msingi itakayotumika kwa usafirishaji na bili.','Address labels' => 'Lebo za anwani','Allow customers to add a custom label for each address' => 'Ruhusu wateja kuongeza lebo maalum kwa kila anwani','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Lebo za anwani hurahisisha wateja kutofautisha kati ya anwani zao zilizohifadhiwa (yaani: &quot;Nyumba ya Mama&quot;). Lebo za anwani ni za faragha kwa wateja, na hazitaonyeshwa au kuchapishwa kwenye ukurasa wa maelezo ya agizo au ankara.','Display layout' => 'Mpangilio wa onyesho','Choose how saved addresses are displayed at checkout and on the cart.' => 'Chagua jinsi anwani zilizohifadhiwa zinavyoonyeshwa wakati wa kulipa na kwenye kikapu.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Hutumika wakati wa kulipa na kwenye kikapu. Anwani zilizohifadhiwa kwenye ukurasa wa akaunti hutumia mpangilio wa kadi kila wakati.','Address cards' => 'Kadi za anwani','Address list' => 'Orodha ya anwani','Dropdown field' => 'Sehemu ya kunjuzi','Address search' => 'Utafutaji wa anwani','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Onyesha kichujio cha utafutaji wa anwani kwenye sehemu ya mbele wakati mteja ana angalau idadi hii ya anwani zilizohifadhiwa zinazopatikana.','Not used when display layout is set to dropdown field.' => 'Haitumiki wakati mpangilio wa onyesho umewekwa kwenye sehemu ya kushuka.','Addresses' => 'Anwani','Enable cart page optimizations to see more options' => 'Washa uboreshaji wa ukurasa wa rukwama ili kuona chaguo zaidi','Sticky order summary' => 'Muhtasari wa mpangilio unaonata','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Chagua mahali pa kuonyesha sehemu ya misimbo ya kuponi kwenye ukurasa wa kikapu. Inatumika tu wakati kikapu cha AJAX kimewashwa, na ikiwa matumizi ya misimbo ya kuponi yamewashwa katika mipangilio ya WooCommerce.','Layout of cross-sell' => 'Mpangilio wa mauzo mtambuka','Cross-sells displayed' => 'Mauzo ya mtambuka yanaonyeshwa','Items' => 'Vitu','Cart page optimization' => 'Uboreshaji wa ukurasa wa rukwama','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Kipe kikapu chako mpangilio uleule ulio wazi, unaolenga ubadilishaji kama vile malipo yako.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Linganisha mpangilio wa kikapu na ukurasa wa kulipa kwa safari thabiti ya ununuzi.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Weka kikapu kikisasishwa kila wakati chinichini, hakuna upakiaji upya wa ukurasa mzima wakati idadi inabadilika.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Weka misimbo ya kuponi, usafirishaji, na mauzo mtambuka mahali ambapo yanabadilisha bidhaa vizuri zaidi.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Weka muhtasari wa agizo ukionekana unaposogeza, na ongeza alama za uaminifu ambapo wanunuzi wanahitaji uhakikisho.','Columns' => 'Safu wima','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Mitindo ya jumla ya hatua za kulipa, muhtasari wa agizo na sehemu zingine. Inatumika kwa malipo mengine, kikapu, asante (agizo limepokelewa), na tazama kurasa za agizo.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Unapotumia mpangilio wa <em>&quot;safu wima 1&quot;</em> pamoja na kiolezo cha muundo wa <em>&quot;Gawanya&quot;</em> , safu wima ya kulia huonyeshwa tu ikiwa eneo la wijeti ya upau wa pembeni wa ukurasa linatumika (Upau wa Pembeni wa Malipo, Upau wa Pembeni wa Kikapu, au Upau wa Pembeni wa Agizo Uliopokelewa). Vinginevyo ukurasa unabaki kama safu wima moja yenye mitindo ya Gawanya.','Split column background' => 'Gawanya mandharinyuma ya safu wima','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Chagua rangi ya usuli kwa safu wima ya pili ya muundo wa Gawanya. Acha tupu ili kutumia rangi ya usuli ya muhtasari wa mpangilio.','Page templates' => 'Violezo vya ukurasa','Checkout template' => 'Kiolezo cha Malipo','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Inapendekezwa kwa vikwazo vichache wakati wa kulipa. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Soma utafiti kuhusu kuachwa kwa kikapu</a> .','Sticky progress bar' => 'Upau wa maendeleo unaonata','Progress bar style' => 'Mtindo wa upau wa maendeleo','Order totals' => 'Jumla ya maagizo','Background color' => 'Rangi ya mandharinyuma','Action link' => 'Kiungo cha vitendo','Mobile order summary' => 'Muhtasari wa agizo la simu','Mobile initial state' => 'Hali ya mwanzo ya simu','Enable editing cart items at checkout' => 'Washa uhariri wa vipengee vya kikapu wakati wa kulipa','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Ruhusu wateja kubadilisha idadi ya bidhaa au kuondoa bidhaa moja kwa moja kwenye ukurasa wa malipo.','Cart item errors' => 'Hitilafu za bidhaa za kikapu','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Inatumika tu wakati msimbo wa kuponi unaonyeshwa kama sehemu tofauti kwenye kurasa za malipo au rukwama, na ikiwa matumizi ya misimbo ya kuponi yamewezeshwa katika mipangilio ya WooCommerce.','Coupon codes position' => 'Nafasi ya misimbo ya kuponi','Apply coupon button' => 'Kitufe cha kutumia kuponi','Select style of the "apply coupon" button.' => 'Chagua mtindo wa kitufe cha &quot;tumia kuponi&quot;.','Address line 2' => 'Mstari wa anwani 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Mpangilio huu unashirikiwa kati ya sehemu za Malipo na sehemu za kuchukua za Karibu. Kwenye sehemu ya kuchukua za Karibu, pia huamua kama kiteuzi cha Usafirishaji/Kuchukua kinaonekana ndani ya sehemu ya njia ya usafirishaji (kabla ya anwani) au kama sehemu tofauti (baada).','Customer accounts' => 'Akaunti za wateja','Guest checkout' => 'Malipo ya wageni','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Chaguo za kulipa kwa wageni, kuingia, na kuunda akaunti kutoka ukurasa wa mipangilio ya Akaunti za WooCommerce. Zinasimamiwa hapa kwa urahisi wako, na kwa hivyo unaweza kutumia thamani tofauti kwa kila wasifu wa mipangilio.','Allow customers to checkout without an account' => 'Ruhusu wateja kulipa bila akaunti','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Inapendekezwa</strong> ili wateja wasiombwe kufungua akaunti au kuingia wakati wa kulipa, jambo ambalo linaweza kupunguza viwango vya ubadilishaji.','When disabled, customers must log in or create an account to complete the purchase.' => 'Wakizimwa, wateja lazima waingie au wafungue akaunti ili kukamilisha ununuzi.','Login at checkout' => 'Ingia wakati wa kulipa','Enable log-in during checkout' => 'Washa kuingia wakati wa kulipa','Show a link for returning customers to log in from the checkout page.' => 'Onyesha kiungo kwa wateja wanaorejea ili waweze kuingia kutoka ukurasa wa kulipa.','Account creation' => 'Uundaji wa akaunti','Allow customers to create an account during checkout' => 'Waruhusu wateja kufungua akaunti wakati wa kulipa','Customers can create an account before placing their order.' => 'Wateja wanaweza kufungua akaunti kabla ya kuweka oda yao.','Allow customers to create an account from the My account page' => 'Ruhusu wateja kuunda akaunti kutoka ukurasa wa Akaunti yangu','Customers can register a new account from the My account page.' => 'Wateja wanaweza kusajili akaunti mpya kutoka ukurasa wa Akaunti Yangu.','Username' => 'Jina la mtumiaji','Generate from customer\'s name' => 'Tengeneza kutoka kwa jina la mteja','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Inapendekezwa</strong> ili wateja wasiulizwe kuchagua jina la mtumiaji wakati wa kulipa, jambo ambalo linaweza kupunguza viwango vya ubadilishaji.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Jina la mtumiaji hutolewa kutokana na jina la mteja, au kutoka kwa anwani ya barua pepe wakati jina haliwezi kutumika.','Password' => 'Nenosiri','Send password setup link' => 'Tuma kiungo cha usanidi wa nenosiri','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Inapendekezwa</strong> ili wateja wasiombwe kuweka nenosiri wakati wa kulipa, jambo ambalo linaweza kupunguza viwango vya ubadilishaji.','Customers receive an email to create their password securely.' => 'Wateja hupokea barua pepe ili kuunda nenosiri lao kwa usalama.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Waruhusu wateja waliosajiliwa kukamilisha malipo bila kuingia na kuhusisha agizo na akaunti yao iliyopo wakati maelezo ya mawasiliano yanapolingana.','Existing account message' => 'Ujumbe wa akaunti uliopo','Let customers create an account after placing their order, from the thank you page.' => 'Waruhusu wateja wafungue akaunti baada ya kuweka oda yao, kutoka ukurasa wa shukrani.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Chaguo katika sehemu hii zinapatikana wakati malipo ya mgeni na ulinganishaji wa akaunti vimewashwa. Washa vipengele vyote viwili hapo juu ili kusanidi uundaji wa akaunti uliocheleweshwa.','Enable delayed account creation' => 'Wezesha uundaji wa akaunti uliochelewa','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Wezesha uundaji wa akaunti uliocheleweshwa wakati malipo ya wageni na ulinganishaji wa akaunti umewezeshwa.','Section position' => 'Nafasi ya sehemu','Before customer details section' => 'Sehemu ya maelezo ya mteja kabla ya','After customer details section' => 'Sehemu ya maelezo ya baada ya mteja','Account creation benefits' => 'Faida za kuunda akaunti','Leaving the field empty will display the default text.' => 'Kuacha sehemu tupu kutaonyesha maandishi chaguo-msingi.','Inline buttons' => 'Vifungo vilivyo ndani ya mstari','Required fields' => 'Sehemu zinazohitajika','Enable gift message fields at checkout' => 'Washa sehemu za ujumbe wa zawadi wakati wa kulipa','Expanded gift message' => 'Ujumbe wa zawadi uliopanuliwa','Display gift message field always expanded' => 'Sehemu ya ujumbe wa zawadi ya onyesho hupanuliwa kila wakati','Gift message in order details' => 'Ujumbe wa zawadi katika maelezo ya mpangilio','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Hakuna miunganisho inayopatikana kwa sasa katika sehemu hii. Chaguo zinazohusiana na kila programu-jalizi na mandhari zitaonekana hapa tu wakati programu-jalizi au mandhari hiyo imewashwa.','Phone fields' => 'Sehemu za simu','Field visibility' => 'Mwonekano wa uwanja','Field position' => 'Nafasi ya uwanjani','Phone country code & validation' => 'Nambari ya simu ya nchi na uthibitisho','Country' => 'Nchi','Enable country on phone fields' => 'Washa sehemu za simu za nchi','Filter countries for shipping or billing' => 'Chuja nchi kwa ajili ya usafirishaji au bili','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Weka kikomo cha kiteuzi cha nchi kwenye kila sehemu ya simu kwa nchi zinazoruhusiwa kwa usafirishaji au bili kwenye duka lako.','Validation' => 'Uthibitisho','Enable simple validation based on country rules' => 'Wezesha uthibitishaji rahisi kulingana na sheria za nchi','Checks that the phone number is valid for the selected country, including country code and length.' => 'Huangalia kwamba nambari ya simu ni halali kwa nchi iliyochaguliwa, ikijumuisha msimbo wa nchi na urefu.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Hakikisha kwa makini zaidi kwamba nambari hiyo ni ya simu halali, laini isiyobadilika, au aina nyingine inayokubalika kwa nchi iliyochaguliwa. Huenda ikakataa baadhi ya nambari halali.','Validation types' => 'Aina za uthibitishaji','Placeholders' => 'Vishikilia nafasi','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Hakuna funguo za leseni za kudhibiti kwa sasa. Funguo za leseni zitaonekana hapa wakati programu-jalizi au programu-jalizi ya Fluid Checkout iliyoidhinishwa inapotumika.','Default delivery type' => 'Aina chaguomsingi ya uwasilishaji','Choose which delivery type will be selected by default.' => 'Chagua aina ya uwasilishaji itakayochaguliwa kwa chaguo-msingi.','Shipping zone fields' => 'Sehemu za eneo la usafirishaji','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Chagua sehemu zipi zitaonyeshwa kwa sehemu za kichujio cha eneo la usafirishaji la eneo la kuchukua mizigo. Acha tupu ili kuonyesha chaguo zote zinazopatikana.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Sehemu hizi zitaonyeshwa kama kichujio cha mbinu za usafirishaji wa ndani. Sehemu zingine zinaweza kuonekana wakati wa kulipa zisipochaguliwa hapa, ikiwa programu-jalizi zinazooana zinahitaji zifanye kazi vizuri.','Order shipping address' => 'Anwani ya usafirishaji wa oda','Order pay page optimization' => 'Uboreshaji wa ukurasa wa malipo ya agizo','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Toa maagizo yasiyolipwa mpangilio uleule ulio wazi, unaolenga ubadilishaji kama vile malipo.','Optimize the layout of the order pay page for orders pending payment.' => 'Boresha mpangilio wa ukurasa wa malipo wa agizo kwa ajili ya maagizo yanayosubiri malipo.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Linganisha hali ya malipo ya agizo na malipo yako kwa safari thabiti ya ununuzi.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Ongeza alama na beji za uaminifu ambapo wanunuzi wanahitaji uhakikisho kabla ya kulipa.','Thank you page optimization' => 'Asante kwa uboreshaji wa ukurasa','Make the thank you page and order details clearer for customers after they buy.' => 'Fanya ukurasa wa shukrani na maelezo ya kuagiza yawe wazi zaidi kwa wateja baada ya kununua.','Optimize the thank you page and account order details with a clearer layout.' => 'Boresha ukurasa wa shukrani na maelezo ya agizo la akaunti kwa mpangilio ulio wazi zaidi.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Onyesha maendeleo ya hali ya mpangilio, vitendo, vipakuliwa, na madokezo ambapo yanaeleweka.','Customize order details sections on email notifications.' => 'Badilisha sehemu za maelezo ya agizo kwenye arifa za barua pepe.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Ongeza alama na beji za uaminifu ambapo wanunuzi wanahitaji uhakikisho baada ya ununuzi.','Email notifications' => 'Arifa za barua pepe','Enable thank you page and order details optimizations to see more options' => 'Washa ukurasa wa shukrani na uboreshaji wa maelezo ya agizo ili kuona chaguo zaidi','Use wide layout on thank you page' => 'Tumia mpangilio mpana kwenye ukurasa wa shukrani','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Chaguo hizi huathiri ukurasa wa shukrani, angalia maelezo ya agizo kwenye kurasa za akaunti na arifa za barua pepe.','Save settings' => 'Hifadhi mipangilio','Docs' => 'Hati','Cart' => 'Kikapu','Thank you' => 'Asante','Address autocomplete' => 'Kukamilisha anwani kiotomatiki','Trust badges' => 'Beji za uaminifu','You do not have permission to save these settings.' => 'Huna ruhusa ya kuhifadhi mipangilio hii.','Invalid save request.' => 'Ombi batili la kuhifadhi.','Your settings have been saved.' => 'Mipangilio yako imehifadhiwa.','Saving...' => 'Inahifadhi...','Settings could not be saved. Please try again.' => 'Mipangilio haikuweza kuhifadhiwa. Tafadhali jaribu tena.','Dismiss notice' => 'Ondoa taarifa','Open settings menu' => 'Fungua menyu ya mipangilio','Close settings menu' => 'Funga menyu ya mipangilio','Preview' => 'Hakikisho','Expand preview' => 'Panua onyesho la kuchungulia','Collapse preview' => 'Kunja onyesho la kuchungulia','Show header and footer' => 'Onyesha kichwa cha habari na kijachini','Hide header and footer' => 'Ficha kichwa cha habari na kijachini','Page preview' => 'Hakikisho la ukurasa','Preview viewport' => 'Hakiki mlango wa kutazama','Tablet' => 'Kompyuta kibao','Desktop' => 'Eneo-kazi','Preview width' => 'Upana wa hakikisho','Decrease width' => 'Punguza upana','Preview width in pixels' => 'Upana wa hakikisho katika pikseli','Increase width' => 'Ongeza upana','Preview as' => 'Hakiki kama','Guest' => 'Mgeni','Logged in' => 'Umeingia','Preview page' => 'Ukurasa wa hakikisho','Expand preview for a closer look' => 'Panua onyesho la kukagua kwa ajili ya kuangalia kwa karibu zaidi','Available with %s.' => 'Inapatikana na %s.','Turn them on' => 'Washa','Optimizations for this page are turned off. %s to preview the page.' => 'Uboreshaji wa ukurasa huu umezimwa. %s ili kuhakiki ukurasa.','%s preview' => 'Onyesho la awali la %s','Isolated session · nothing is saved' => 'Kipindi kilichotengwa · hakuna kilichohifadhiwa','Usage tracking' => 'Ufuatiliaji wa matumizi','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Tuma ripoti za mazingira ya tovuti zisizo nyeti ili kusaidia Fluid Checkout kuboresha utangamano. Ripoti hazitumwi hadi ziwezeshwe katika chaguo zilizo hapa chini.','Send usage tracking reports to Fluid Checkout' => 'Tuma ripoti za ufuatiliaji wa matumizi kwa Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Ripoti hizi hutusaidia kuboresha utangamano na usaidizi kwa tovuti yako na hutumwa kila wiki inapowezeshwa.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Hakuna mteja, mtumiaji wa msimamizi, au data nyingine yoyote nyeti iliyojumuishwa katika ripoti.','Basic environment info' => 'Taarifa za msingi za mazingira','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'WordPress, PHP, WooCommerce, orodha ya mandhari, na programu-jalizi. Hujumuishwa kila wakati wakati kuripoti kunawezeshwa. Hutusaidia kuelewa mazingira ambayo tovuti yako inafanya kazi.','Plugin settings' => 'Mipangilio ya programu-jalizi','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Hutuma mipangilio ya programu-jalizi ya Fluid Checkout ili kusaidia na maombi ya usaidizi na hutusaidia kuelewa jinsi unavyotumia programu-jalizi zetu.','Coming soon' => 'Inakuja hivi karibuni','Sales metrics' => 'Vipimo vya mauzo','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Hesabu ya oda za kila mwezi na jumla ya mauzo kwa mwaka mmoja kabla ya kusakinisha Fluid Checkout hadi leo. Inatusaidia kuelewa ikiwa unapata pesa zaidi ukitumia programu-jalizi zetu zilizosakinishwa. Hakuna data ya mteja au mtumiaji inayotumwa.','Utilities' => 'Huduma za umma','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Tumia vipengele vya kunjuzi <code>TomSelect</code> badala ya <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect ni sehemu rahisi zaidi ya uteuzi wa menyu kunjuzi ambayo haina uwezekano mkubwa wa kufanya makosa kama Select2, huku ikitoa utendaji sawa.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Huweka ukubwa wa fonti ndani ya sehemu za fomu kuwa pikseli 16 kwenye kurasa zilizoboreshwa na programu-jalizi hii ili kuepuka kukuza kiotomatiki wakati wa kuingiliana na sehemu za fomu kwenye vifaa vidogo.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari na vivinjari vingine vinaweza kukuza kiotomatiki kwenye vifaa vya mkononi ili kurahisisha usomaji wa maandishi wakati ukubwa wa fonti ni mdogo kuliko pikseli 16.','Enable script processing tracking on the browser console.' => 'Washa ufuatiliaji wa usindikaji wa hati kwenye koni ya kivinjari.','Unminified assets' => 'Mali zisizopunguzwa','Google Maps scripts' => 'Hati za Ramani za Google','Do not remove duplicate Google Maps scripts' => 'Usiondoe nakala za hati za Ramani za Google','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Inapowezeshwa, nakala za hati za Ramani za Google HAZITAONDOLEWA jambo ambalo linaweza kusababisha hitilafu na matatizo ya utendaji. Tumia chaguo hili pekee wakati wa kutatua matatizo.','Widget areas' => 'Maeneo ya wijeti','Last step on mobile' => 'Hatua ya mwisho kwenye simu','Display widgets only at last step on mobile' => 'Onyesha wijeti katika hatua ya mwisho kwenye simu pekee','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Onyesha wijeti za beji ya uaminifu wa malipo unapoangalia hatua ya mwisho ya malipo kwenye vifaa vya mkononi pekee','Standard' => 'Kiwango','VAT number field' => 'Sehemu ya nambari ya VAT','Add a VAT number field to the billing form.' => 'Ongeza sehemu ya nambari ya VAT kwenye fomu ya bili.','Field label' => 'Lebo ya sehemu','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Weka lebo ya sehemu ya nambari ya VAT (yaani nambari ya VAT). Kwenye tovuti za lugha nyingi, ni bora kuacha sehemu hii ikiwa tupu na kutafsiri mfuatano asilia.','VAT Number' => 'Nambari ya VAT','EU-VAT' => 'EU-VAT','Enable the VAT number field to see more options' => 'Washa sehemu ya nambari ya VAT ili kuona chaguo zaidi','VAT validation' => 'Uthibitisho wa VAT','Validate VAT number field for EU-VAT during checkout' => 'Thibitisha sehemu ya nambari ya VAT kwa EU-VAT wakati wa kulipa','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Huangalia kama Nambari ya VAT iliyotolewa ni nambari halali ya VAT iliyosajiliwa kwenye Hifadhidata ya Ulaya ya VIES (Mfumo wa Kubadilishana Taarifa wa VAT).','Shop VAT number' => 'Nambari ya VAT ya duka','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Nambari ya VAT ya duka iliyotumika kuomba uthibitisho wa EU-VAT, na kuchapishwa kwenye ankara.<br> <strong>Tunapendekeza sana kuongeza nambari yako ya VAT ya Duka</strong> kwani vinginevyo matokeo ya mashauriano ya VIES yanaweza yasiwe halali kwa madhumuni ya uhasibu.<br> Yaani.: <code>ATU99999999</code> au <code>EE999999999</code> .','Reverse charge' => 'Chaji ya kinyume','Apply reverse charge mechanism' => 'Tumia utaratibu wa kuchaji kinyume','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Weka kiwango cha kodi hadi sifuri na uonyeshe &quot;Tozo ya kinyume&quot; kwenye ankara wakati nambari ya VAT ya mteja ni halali. Maandishi tofauti ya &quot;Tozo ya kinyume&quot; yanaweza kuhitajika kulingana na nchi ya duka.','Same country' => 'Nchi moja','Apply reverse charge mechanism for transactions in the shop country:' => 'Tumia utaratibu wa kuchaji kinyume kwa miamala katika nchi ya duka:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Huwezesha kutumia utaratibu wa malipo ya nyuma kwa miamala kati ya makampuni katika nchi moja na duka.','Reverse charge exceptions' => 'Vighairi vya malipo ya kinyume','Select additional countries to skip applying the reverse charge mechanism.' => 'Chagua nchi zingine ili kuruka kutumia utaratibu wa kuchaji kinyume.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Ushuru utatozwa kwa maagizo kutoka nchi hizi hata wakati nambari halali ya VAT itatolewa.','Reverse charge label on invoices' => 'Lebo ya malipo ya kinyume kwenye ankara','Set the label of "reverse charge" on the checkout page and order details.' => 'Weka lebo ya &quot;malipo ya nyuma&quot; kwenye ukurasa wa malipo na maelezo ya oda.','Reverse charge text on invoices' => 'Maandishi ya malipo ya kinyume kwenye ankara','Set the label of "reverse charge" text on invoices.' => 'Weka lebo ya maandishi ya &quot;malipo ya nyuma&quot; kwenye ankara.','Tax to be paid on reverse charge basis' => 'Kodi itakayolipwa kwa msingi wa malipo ya nyuma','Company name' => 'Jina la kampuni','Autocomplete company name from VAT number' => 'Jaza jina la kampuni kiotomatiki kutoka nambari ya VAT','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Jaza jina la kampuni ya bili kulingana na nambari halali ya VAT iliyotolewa na mteja.','Company name editing' => 'Uhariri wa jina la kampuni','Allow editing of auto-filled company name' => 'Ruhusu uhariri wa jina la kampuni lililojazwa kiotomatiki','When enabled, customers can change the company name associated with the provided VAT number.' => 'Inapowezeshwa, wateja wanaweza kubadilisha jina la kampuni linalohusiana na nambari ya VAT iliyotolewa.','EU-VAT for digital goods' => 'EU-VAT kwa bidhaa za kidijitali','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Kuanzia Januari 1, 2015, marekebisho yamefanywa kwa kanuni za VAT za EU kuhusu bidhaa za kidijitali, na kuathiri miamala ya B2C pekee. VAT kwa bidhaa za kidijitali lazima ihesabiwe kulingana na eneo la mteja, na ushahidi wa hili unahitaji kukusanywa (anwani ya IP na anwani ya bili).','Tax classes for digital goods' => 'Madarasa ya kodi kwa bidhaa za kidijitali','Select some tax classes' => 'Chagua baadhi ya madarasa ya kodi','Location evidence' => 'Ushahidi wa eneo','Collect customer\'s location evidence' => 'Kusanya ushahidi wa eneo la mteja','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Huhifadhi anwani ya IP na kuithibitisha dhidi ya anwani ya bili ya mteja. Mteja lazima athibitishe anwani yake ya bili kwa kuchagua kisanduku cha kuteua kwenye ukurasa wa malipo ikiwa nchi kutoka kwa anwani yake ya bili na IP hailingani.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Chaguo hili linadhibitiwa katika Fluid Checkout. <a href="%s">Libadilishe katika mipangilio ya akaunti za Wateja</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Chaguo hili linadhibitiwa katika Fluid Checkout. Libadilishe chini ya Fluid Checkout &gt; Akaunti za wateja.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Chaguo hili linadhibitiwa katika Fluid Checkout. Sehemu ya usafirishaji huwekwa kila wakati kuwa &quot;Anwani chaguo-msingi ya usafirishaji wa mteja&quot; wakati Fluid Checkout inapowashwa. Wateja bado wanaweza kutoa anwani tofauti za usafirishaji na bili wakati wa malipo.<br><br> Chaguo la kuweka anwani chaguo-msingi ya bili kuwa sawa na anwani ya usafirishaji linapatikana katika <a href="%s">mipangilio ya Fluid Checkout</a> .','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Chaguo hili linadhibitiwa katika Fluid Checkout. Sehemu ya usafirishaji huwekwa kila wakati kuwa &quot;Anwani chaguo-msingi ya usafirishaji wa mteja&quot; wakati Fluid Checkout inapowashwa. Wateja bado wanaweza kutoa anwani tofauti za usafirishaji na bili wakati wa malipo.<br><br> Chaguo la kuweka anwani chaguo-msingi ya bili kuwa sawa na anwani ya usafirishaji linapatikana katika WooCommerce &gt; Mipangilio &gt; Malipo ya Maji.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Mipangilio hii imehamishiwa kwenye WP Admin &gt; Fluid Checkout &gt; Mipangilio.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Kichupo hiki cha Mipangilio ya WooCommerce kimeondolewa kwenye huduma na kitaondolewa katika Fluid Checkout 6.0.','Go to settings page' => 'Nenda kwenye ukurasa wa mipangilio','Hide this tab permanently' => 'Ficha kichupo hiki kabisa','Site report preview' => 'Hakikisho la ripoti ya tovuti','This is the data that would be included in the next site environment report based on your current settings.' => 'Hii ndiyo data ambayo itajumuishwa katika ripoti inayofuata ya mazingira ya tovuti kulingana na mipangilio yako ya sasa.','Loading report preview...' => 'Inapakia hakikisho la ripoti...','Could not load the site report preview. Try again.' => 'Haikuweza kupakia onyesho la kuchungulia ripoti ya tovuti. Jaribu tena.','Could not send the site report. Try again.' => 'Haikuweza kutuma ripoti ya tovuti. Jaribu tena.','Site report sent successfully.' => 'Ripoti ya tovuti imetumwa kwa mafanikio.','Enable and send now' => 'Wezesha na utume sasa','Close' => 'Funga','A site report request is already in progress. Try again in a moment.' => 'Ombi la ripoti ya tovuti tayari linaendelea. Jaribu tena baada ya muda mfupi.','Site environment reporting is disabled.' => 'Kuripoti mazingira ya tovuti kumezimwa.','No site report data is available to send.' => 'Hakuna data ya ripoti ya tovuti inayopatikana ya kutuma.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Kikoa hiki cha tovuti hakiwezi kutuma ripoti za mazingira (vikoa vya ndani au vya maendeleo havijajumuishwa).','A site report was sent recently. Try again later.' => 'Ripoti ya tovuti ilitumwa hivi majuzi. Jaribu tena baadaye.','The site report could not be sent. Try again later.' => 'Ripoti ya tovuti haikuweza kutumwa. Jaribu tena baadaye.','Site environment reporting is not available.' => 'Ripoti ya mazingira ya tovuti haipatikani.','No site report data is available for the selected settings.' => 'Hakuna data ya ripoti ya tovuti inayopatikana kwa mipangilio iliyochaguliwa.','You are not allowed to manage site reports.' => 'Huruhusiwi kudhibiti ripoti za tovuti.','PRO feature' => 'Kipengele cha PRO','Other plugins' => 'Programu-jalizi zingine','Get only this add-on &mdash; %s' => 'Pata programu hii jalizi pekee — %s','Install add-on' => 'Sakinisha programu jalizi','Upgrade to PRO &mdash; %s' => 'Boresha hadi PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Pata %2$s</a> ili kufungua chaguo hizi.','Add-on' => 'Nyongeza','View documentation' => 'Tazama hati','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Maombi yanahitaji mtumiaji wa WordPress aliyeingia. Acha kitambulisho cha mtumiaji ili kutumia data ya mtumiaji wa sasa, au toa kitambulisho cha mtumiaji ili kulenga akaunti nyingine wakati mpigaji anaweza kuhariri mtumiaji huyo (uwezo wa kuhariri_mtumiaji). Maombi ambayo hayajathibitishwa hurejesha fc_api_forbidden. Kitambulisho cha mtumiaji batili hurejesha fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 yenye { &quot;data&quot;: { ... } } wakati kidhibiti kinarudisha mzigo wa malipo.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 yenye { &quot;success&quot;: true } wakati hakuna mzigo wa malipo (kwa mfano DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Kushindwa hurejesha hitilafu ya WordPress REST JSON kutoka WP_Error (msimbo, ujumbe, data.status). Misimbo ya waya hutumia kiambishi awali cha fc_api_*.','Forbidden access.' => 'Ufikiaji uliopigwa marufuku.','Target user was not found.' => 'Mtumiaji lengwa hakupatikana.','This feature is not available.' => 'Kipengele hiki hakipatikani.','A required address field is missing.' => 'Sehemu ya anwani inayohitajika haipo.','Postcode or ZIP is invalid.' => 'Nambari ya posta au ZIP si sahihi.','Phone number is invalid.' => 'Nambari ya simu si sahihi.','State or county is invalid.' => 'Jimbo au kaunti si sahihi.','Country is invalid or has no address fields.' => 'Nchi si sahihi au haina sehemu za anwani.','The request could not be processed.' => 'Ombi halikuweza kushughulikiwa.','Back to previous step' => 'Rudi kwenye hatua iliyotangulia','Skip to settings' => 'Ruka hadi kwenye mipangilio','Start over and return to the first guided setup step' => 'Anza upya na urudi kwenye hatua ya kwanza ya usanidi iliyoongozwa','Start over' => 'Anza upya','Please complete all sub-steps before continuing.' => 'Tafadhali kamilisha hatua ndogo zote kabla ya kuendelea.','Expand' => 'Panua','Collapse' => 'Kunja','Skip' => 'Ruka','Mark as complete' => 'Weka alama kama imekamilika','Mark as incomplete' => 'Weka alama kama haijakamilika','View full-size image: %s' => 'Tazama picha ya ukubwa kamili: %s','Full-size setup guide image' => 'Picha ya mwongozo wa usanidi wa ukubwa kamili','Close image' => 'Funga picha','Fluid Checkout Guided Setup' => 'Usanidi Unaoongozwa na Kulipa kwa Maji','Welcome' => 'Karibu','Explore your checkout' => 'Chunguza malipo yako','All set' => 'Zote zimewekwa','You do not have permission to access this page.' => 'Huna ruhusa ya kufikia ukurasa huu.','Go to step %1$d: %2$s' => 'Nenda kwenye hatua ya %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Mpangilio huu unaoongozwa hukusaidia kufahamu Fluid Checkout. Hatua zilizo hapa chini ni vihifadhi nafasi kwa sasa.','Continue to the next step when you are ready.' => 'Endelea hadi hatua inayofuata ukiwa tayari.','Open your store checkout to see Fluid Checkout in action.' => 'Fungua malipo yako ya dukani ili uone Malipo ya Fluid yakiendelea.','View checkout page' => 'Tazama ukurasa wa malipo','You can return to Fluid Checkout settings to continue configuring your store.' => 'Unaweza kurudi kwenye mipangilio ya Fluid Checkout ili kuendelea kusanidi duka lako.','Review checkout and cart settings' => 'Kagua mipangilio ya malipo na kikapu','Explore add-ons from the dashboard' => 'Gundua programu jalizi kutoka kwenye dashibodi','Finish & go to settings' => 'Maliza na uende kwenye mipangilio','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Sasisha chaguo la mwonekano wa sehemu ya simu ya bili kutoka thamani ya zamani ili ilingane na mikataba ya WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Sasisha chaguo la mwonekano wa sehemu ya simu ya usafirishaji kutoka thamani ya zamani ili ilingane na mikataba ya WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Nakili mpangilio wa rangi ya usuli wa muhtasari wa mpangilio kwenye chaguo jipya la rangi ya usuli ya safu wima ya pili ya muundo wa Mgawanyiko.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Kipengele cha sehemu teule kilichoboreshwa huzimwa kila wakati unapotumia programu-jalizi ya Biteship.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Nafasi ya mpangilio wa mahali huwekwa kila wakati kuwa &quot;Chini ya muhtasari wa mpangilio&quot; unapotumia Soko la Ujerumani. Programu-jalizi hiyo inahitaji kitufe cha mpangilio wa mahali na visanduku halali vya kuteua vionyeshwe chini ya muhtasari wa mpangilio.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Nafasi ya mpangilio wa mahali huwekwa kila wakati kuwa &quot;Chini ya muhtasari wa mpangilio&quot; unapotumia Kijerumani kwa WooCommerce. Programu-jalizi hiyo inahitaji kitufe cha mpangilio wa mahali na visanduku vya kuteua halali vionyeshwe chini ya muhtasari wa mpangilio.','Edit pickup locations' => 'Hariri maeneo ya kuchukuliwa','Use local pickup label from WooCommerce settings' => 'Tumia lebo ya kuchukua kutoka kwa mipangilio ya WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Inapowashwa, lebo ya chaguo la kuchukua kwenye malipo inalingana na kichwa kutoka kwa mipangilio ya eneo la kuchukua la WooCommerce. Inapozimwa, lebo hutumia maandishi ya &quot;Kuchukua kwa Ndani&quot; yanayoweza kutafsiriwa kutoka kwa Fluid Checkout.','Button label for applying coupon codesApply' => 'Omba','Checkout step titleContact' => 'Wasiliana','Checkout step titleShipping' => 'Usafirishaji','Checkout step titleBilling' => 'Bili','Checkout step titlePayment' => 'Malipo','Checkout substep change link labelChange' => 'Badilika','Checkout substep save link labelSave changes' => 'Hifadhi mabadiliko','Substep review textNone.' => 'Hakuna.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Hakuna picha iliyochaguliwa.','Settings sectionCart' => 'Mkokoteni','Settings sectionOrder pay' => 'Malipo ya agizo','Settings sectionThank you' => 'Asante','Settings section titleIntegrations' => 'Ushirikiano','Settings section titleLicense keys' => 'Vifunguo vya leseni','Captcha positionBefore place order section' => 'Kabla ya sehemu ya kuagiza','Captcha positionBefore place order button' => 'Kabla ya kuweka kitufe','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Funga','Log in link label at checkout contact stepLog in' => 'Ingia','Log in separator label at for when guest checkout is disabledOr continue below' => 'Au endelea hapa chini','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Au endelea kama mgeni','Clear image selection on admin pages.Remove image' => 'Ondoa picha','shipping packagesShipping %d' => 'Usafirishaji %d','shipping packagesShipping' => 'Usafirishaji','Used as fallback for "Proceed to next step" button labelnext step' => 'hatua inayofuata','Substep review checkbox valueYes' =>